<?php declare(strict_types=1);
require __DIR__.'/balance-club-tax-filing.php';
use Kulturhus\Verein\{BalanceTaxFiling,TaxFilings,BalanceTaxValues,BalanceTaxFeedback};
use Kulturhus\Verein\Tests\MySqlFixture;
$before=MySqlFixture::rows($db,'balance_years');
$wholeProfile=$clubProfile;$wholeProfile['tax_privileged']=false;$wholeProfile['business_name']='Synthetic complete non-privileged club';
$wid=$service->create(2025,'complete_club_ledger');$wf=$filings->get($wid);$wr=$service->sourceReport($wf);
check($wr['calculation']['annual_result_cents']===4012&&count($wr['entries'])===6,'whole club retains all original journal entries');
check($wf['form_data']['balance_preparation']['profile']['asset_scope']==='whole_club','complete asset scope retained');
check(!isset($wf['form_data']['balance_preparation']['source_binding']),'whole taxable club does not depend on partial allocation');
denied(fn()=>$service->save($wid,1,$clubProfile,$mapping,$review),'whole taxable cannot become privileged via profile edit');
$bad=$wf;$bad['form_data']['balance_preparation']['profile']['source_scope']='approved_club_allocation';denied(fn()=>$service->sourceReport($bad),'scope tampering rejected');
denied(fn()=>(new BalanceTaxFiling($db,'other'))->sourceReport($wf,true),'whole club respects tenant isolation');
denied(fn()=>(new BalanceTaxFiling($db,'club-member'))->create(2025,'complete_club_ledger'),'member cannot create whole-club declaration');
$service->save($wid,1,$wholeProfile,$mapping,$review);check($filings->validate($wid,2)['valid'],'whole-club workflow runs real XML generator');
denied(fn()=>$service->approve($wid,3,true),'treasurer cannot bypass board approval');
$approver->approve($wid,3,true);check($filings->ready($wid,4,'SEND-TEST',true,true)['id']===$wid,'whole club ready only after exact approval');
$html=$render($wid,'club-finance');check(str_contains($html,'Gesamter Verein · nicht steuerbegünstigt')&&str_contains($html,'den gesamten nicht steuerbegünstigten Verein'),'UI labels complete club unambiguously');
file_put_contents(__DIR__.'/balance-whole-club-ui.html',$html);
check($filings->send($wid,4,'dummy','123456','SEND-TEST',true,true)['state']==='sent_test','simulated transport records full profile receipt');
$wf=$filings->get($wid);$feedback=BalanceTaxFeedback::describe($wf,$filings->attempts($wid));
check($feedback['technical']==='confirmed'&&$feedback['later']==='eligibility_review','whole-club later feedback not mislabeled as SGEB exclusion');
denied(fn()=>$filings->send($wid,4,'dummy','123456','SEND-TEST',true,true),'whole duplicate send blocked');
$wn=$service->create(2026,'complete_club_ledger');$service->save($wn,1,$wholeProfile,$mapping,$review);
denied(fn()=>$service->assertCurrent($filings->get($wn)),'whole following year requires actual prior tax proof');
denied(fn()=>$service->carryForward($wn,2,$fid,true),'partial SGEB cannot carry into whole club');
$service->carryForward($wn,2,$wid,true);$nr=$filings->get($wn)['form_data']['balance_preparation']['review'];unset($nr['year'],$nr['journal_sha256']);$nr['complete']=true;
$service->save($wn,3,$wholeProfile,$mapping,$nr);$wv=$service->assertCurrent($filings->get($wn));
check($wv['tax']['capital_total_cents']===104012&&$wv['tax']['annual_result_cents']===0,'complete opening and prior profit retained exactly');
check($filings->validate($wn,4)['valid'],'following full year passes real generator');
check(MySqlFixture::rows($db,'balance_years')===$before,'whole-club declarations never modify closed journal');
$capitalId=$service->create(2025,'complete_club_ledger');$service->save($capitalId,1,$wholeProfile,$mapping,$review);
$service->appendAdjustment($capitalId,2,'current_adjustments','Synthetic capital contribution <not-html>','cash','equity',1000);
$cp=$filings->get($capitalId);$cr=$cp['form_data']['balance_preparation']['review'];$cr['complete']=true;
$cv=BalanceTaxValues::build($service->sourceReport($cp),$cr);$key=array_key_first($cv['capital_comparison']['sources']);
check(!$cv['capital_comparison']['complete']&&count($cv['capital_comparison']['sources'])===1,'capital movement shown as unresolved, not profit');
$crSave=$cr;unset($crSave['year'],$crSave['journal_sha256']);$service->save($capitalId,3,$wholeProfile,$mapping,$crSave);
denied(fn()=>$filings->validate($capitalId,4),'unresolved capital blocks validation');
denied(fn()=>$service->capitalMovements($capitalId,4,[$key=>['kind'=>'withdrawal','reason'=>'wrong side']]),'capital side cannot be reversed');
denied(fn()=>(new BalanceTaxFiling($db,'other'))->capitalMovements($capitalId,4,[]),'capital editing respects club boundary');
$service->capitalMovements($capitalId,4,[$key=>['kind'=>'contribution','reason'=>'Synthetic evidence <not-html>']]);
$cp=$filings->get($capitalId);check(!$cp['form_data']['balance_preparation']['review']['complete']&&$cp['xml_data']===null,'capital review invalidates earlier overall review and XML');
$capitalHtml=$render($capitalId,'club-finance',[],false,'Kapitalbewegungen zuordnen');check(str_contains($capitalHtml,'tax-filing-balance-capital')&&str_contains($capitalHtml,'&lt;not-html&gt;')&&!str_contains($capitalHtml,'<not-html>'),'capital UI presents protected form and escaped evidence');
file_put_contents(__DIR__.'/balance-whole-club-ui.html',$capitalHtml);
$cr=$cp['form_data']['balance_preparation']['review'];unset($cr['year'],$cr['journal_sha256']);$cr['complete']=true;$service->save($capitalId,5,$wholeProfile,$mapping,$cr);
$service->revision($capitalId,6,['status'=>'B','reason'=>'Synthetic corrected tax capital','legal_basis'=>'Synthetic reviewed amendment','source_id'=>$wid,'confirmed'=>true]);
check($filings->validate($capitalId,7)['valid'],'reviewed capital comparison reaches real generator');
$approver->approve($capitalId,8,true);$service->capitalMovements($capitalId,9,[$key=>['kind'=>'contribution','reason'=>'Rechecked evidence']]);
check(!isset($filings->get($capitalId)['form_data']['balance_preparation']['approval']),'capital edits revoke exact board approval');
denied(fn()=>$service->capitalMovements($capitalId,9,[]),'stale capital edit cannot erase newer decision');
putenv('VEREIN_MODE=production');denied(fn()=>$service->create(2025,'complete_club_ledger'),'whole-club feature cannot leak into production');putenv('VEREIN_MODE=synthetic');
if(getenv('VEREIN_TEST_SKIP_BACKUP_ROUNDTRIP')!=='1'){
    $restored=MySqlFixture::restoreBackup($db);foreach(['tax_filings','tax_filing_attempts'] as $table)check(MySqlFixture::rows($db,$table)===MySqlFixture::rows($restored,$table),'restore retains whole-club '.$table);
}else echo "SKIP optional backup roundtrip: dedicated synthetic database\n";
echo "$checks combined filing checks passed; synthetic MySQL and simulated transport only\n";
